import torch

def run(grad_output, indices, num_weights, padding_idx, scale_grad_by_freq):
    return torch.ops.aten.embedding_dense_backward(grad_output, indices, num_weights, padding_idx, scale_grad_by_freq)

def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])

def gen_inputs(ctx, device):
    return {
        "indices": torch.randint(
            0,
            ctx["num_weights"],
            ctx["indices__shape"],
            dtype=_dtype_from_context(ctx, "indices"),
            device=device,
        )
    }
